9	 *
10	 * Unless required by applicable law or agreed to in writing, software
11	 * distributed under the License is distributed on an "AS IS" BASIS,
12	 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
13	 * See the License for the specific language governing permissions and
14	 * limitations under the License.
15	 */
16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "bulk_signup_warning")
67	    private Boolean bulkSignupWarning;
68	
69	    @Column(name = "household_size")
70	    private Integer householdSize;
71	
72	    @Column(name = "postcode")
73	    private String postcode;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    public String getAddress() {
79	        return this.address;
80	    }
81	
82	    public void setAddress(String address) {
83	        this.address = address;
84	    }
85	
86	    public String getCity() {
87	        return this.city;
88	    }
89	
90	    public void setCity(String city) {
91	        this.city = city;
92	    }
93	
94	    public String getTelephone() {
95	        return this.telephone;
96	    }
97	
98	    public void setTelephone(String telephone) {
99	        this.telephone = telephone;
100	    }
101	
102	    public String getEmail() {
103	        return this.email;
104	    }
105	
106	    public void setEmail(String email) {
107	        this.email = email;
108	    }
109	
110	    public LocalDate getRegistrationDate() {
111	        return this.registrationDate;
112	    }
113	
114	    public void setRegistrationDate(LocalDate registrationDate) {
115	        this.registrationDate = registrationDate;
116	    }
117	
118	    public String getCustomerCode() {
119	        return this.customerCode;
120	    }
121	
122	    public void setCustomerCode(String customerCode) {
123	        this.customerCode = customerCode;
124	    }
125	
126	    public String getHouseholdId() {
127	        return this.householdId;
128	    }
129	
130	    public void setHouseholdId(String householdId) {
131	        this.householdId = householdId;
132	    }
133	
134	    public Integer getNamesakeCount() {
135	        return this.namesakeCount;
136	    }
137	
138	    public void setNamesakeCount(Integer namesakeCount) {
139	        this.namesakeCount = namesakeCount;
140	    }
141	
142	    public Boolean getBulkSignupWarning() {
143	        return this.bulkSignupWarning;
144	    }
145	
146	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
147	        this.bulkSignupWarning = bulkSignupWarning;
148	    }
149	
150	    public Integer getHouseholdSize() {
151	        return this.householdSize;
152	    }
153	
154	    public void setHouseholdSize(Integer householdSize) {
155	        this.householdSize = householdSize;
156	    }
157	
158	    public String getPostcode() {
159	        return this.postcode;
160	    }
161	
162	    public void setPostcode(String postcode) {
163	        this.postcode = postcode;
164	    }
165	
166	    /**
167	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
168	     * is the last two digits of the registration date's year (e.g. {@code "NSW-1A2B3C4D-M26"}).
169	     * Derived from the owner's own fields, so it stays consistent with them.
170	     */
171	    @Transient
172	    public String getMembershipNumber() {
173	        if (this.customerCode == null || this.registrationDate == null) {
174	            return null;
175	        }
176	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
177	    }
178	
179	    /**
180	     * The owner's customer-code check digit: the single Luhn check digit (0-9) computed
181	     * over the digits of the customer code. Derived from the owner's own customer code,
182	     * so it stays consistent with it.
183	     */
184	    @Transient
185	    public Integer getCheckDigit() {
186	        if (this.customerCode == null) {
187	            return null;
188	        }
189	        return LuhnCheckDigit.of(this.customerCode);
190	    }
191	
192	    /**
193	     * The owner's membership level, a number from 1 to 3. Every owner starts at level 1;
194	     * one level is added when an email is on file and one more when the owner is unique
195	     * (namesake count of zero). The level is capped at 3, leaving level 4 reserved for
196	     * tenure. Derived from the owner's own fields, so it stays consistent with them.
197	     */
198	    @Transient
199	    public Integer getMembershipLevel() {
200	        int level = 1;
201	        boolean hasEmail = this.email != null && !this.email.isEmpty();
202	        if (hasEmail) {
203	            level++;
204	        }
205	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
206	        if (unique) {
207	            level++;
208	        }
209	        return Math.min(level, 3);
210	    }
211	
212	    /**
213	     * The owner's locality: the canonical region, taken as the region segment of the
214	     * customer code (formatted {@code '<REGION>-<HASH8>'}), so the locality stays
215	     * consistent with the owner's identity. When no customer code has been assigned yet
216	     * it falls back to resolving the region directly from the postcode and city (see
217	     * {@link RegionResolver}), the same rule the customer code itself is built from.
218	     */
219	    @Transient
220	    public String getLocality() {
221	        if (this.customerCode != null) {
222	            int separator = this.customerCode.indexOf('-');
223	            if (separator > 0) {
224	                return this.customerCode.substring(0, separator);
225	            }
226	        }
227	        return RegionResolver.regionFor(this.postcode, this.city);
228	    }
229	
230	    /**
231	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is on
232	     * file, otherwise {@code "PHONE"}. Derived from the owner's own contact details, so it
233	     * stays consistent with them.
234	     */
235	    @Transient
236	    public String getContactPreference() {
237	        boolean hasEmail = this.email != null && !this.email.isEmpty();
238	        return hasEmail ? "EMAIL" : "PHONE";
239	    }
240	
241	    /**
242	     * The owner's identity key: the single derived value used to detect duplicate owners,
243	     * formed as {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
244	     * Two owners are duplicates only when their whole identity keys are equal, so members
245	     * of one household (sharing a household id) but with different telephones stay distinct.
246	     * Derived from the owner's own fields, so it stays consistent with them.
247	     */
248	    @Transient
249	    public String getIdentityKey() {
250	        String telephonePart = this.telephone == null ? "" : this.telephone;
251	        String emailPart = this.email == null ? "" : this.email;
252	        String householdPart = this.householdId == null ? "" : this.householdId;
253	        return telephonePart + "|" + emailPart + "|" + householdPart;
254	    }
255	
256	    /**
257	     * Normalize the registration date before persisting: default it to the server's
258	     * current date when none was supplied, then roll it forward onto a business day so
259	     * every newly persisted owner is registered on a weekday.
260	     */
261	    @PrePersist
262	    void normalizeRegistrationDate() {
263	        if (this.registrationDate == null) {
264	            this.registrationDate = LocalDate.now();
265	        }
266	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
267	    }
268	
269	    protected Set<Pet> getPetsInternal() {
270	        if (this.pets == null) {
271	            this.pets = new HashSet<>();
272	        }
273	        return this.pets;
274	    }
275	
276	    protected void setPetsInternal(Set<Pet> pets) {
277	        this.pets = pets;
278	    }
279	
280	    public List<Pet> getPets() {
281	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
282	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
283	        return Collections.unmodifiableList(sortedPets);
284	    }
285	
286	    public void setPets(List<Pet> pets) {
287	        this.pets = new HashSet<>(pets);
288	    }
289	
290	    public void addPet(Pet pet) {
291	        getPetsInternal().add(pet);
292	        pet.setOwner(this);
293	    }
294	
295	    /**
296	     * Return the Pet with the given name, or null if none found for this Owner.
297	     *
298	     * @param name to test
299	     * @return true if pet name is already in use
300	     */
301	    public Pet getPet(String name) {
302	        return getPet(name, false);
303	    }
304	
305	    /**
306	     * Return the Pet with the given name, or null if none found for this Owner.
307	     *
308	     * @param name to test
309	     * @return true if pet name is already in use
310	     */
311	    public Pet getPet(String name, boolean ignoreNew) {
312	        name = name.toLowerCase();
313	        for (Pet pet : getPetsInternal()) {
314	            if (!ignoreNew || !pet.isNew()) {
315	                String compName = pet.getName();
316	                compName = compName.toLowerCase();
317	                if (compName.equals(name)) {
318	                    return pet;
319	                }
320	            }
321	        }
322	        return null;
323	    }
324	
325	    public Pet getPet(Integer petId) {
326	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
327	    }
328	
329	    @Override
330	    public String toString() {
331	        return new ToStringCreator(this)
332	
333	            .append("id", this.getId())
334	            .append("new", this.isNew())
335	            .append("lastName", this.getLastName())
336	            .append("firstName", this.getFirstName())
337	            .append("address", this.address)
338	            .append("city", this.city)
339	            .append("telephone", this.telephone)
340	            .toString();
341	    }
342	}
